create table if not exists public.commerce_events (id uuid primary key default gen_random_uuid(), user_id uuid null references auth.users(id) on delete set null, store_id uuid null references public.stores(id) on delete set null, product_id uuid null references public.products(id) on delete set null, event_type text not null check(event_type in ('product_view','add_to_cart','checkout_started','order_created','order_paid','order_refunded','search','rfq_created','rfq_awarded')), session_id text null, amount numeric null check(amount is null or amount>=0), currency char(3) null, metadata jsonb not null default '{}'::jsonb, occurred_at timestamptz not null default now()); alter table public.commerce_events enable row level security; drop policy if exists commerce_events_owner_select on public.commerce_events; drop policy if exists commerce_events_insert_own on public.commerce_events; create policy commerce_events_owner_select on public.commerce_events for select to authenticated using(user_id=auth.uid() or exists(select 1 from public.stores s where s.id=store_id and s.vendor_id=auth.uid())); create policy commerce_events_insert_own on public.commerce_events for insert to authenticated with check(user_id=auth.uid()); create index if not exists commerce_events_store_date_idx on public.commerce_events(store_id,occurred_at desc); create index if not exists commerce_events_product_date_idx on public.commerce_events(product_id,occurred_at desc);
create table if not exists public.inventory_forecasts (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id) on delete cascade, store_id uuid not null references public.stores(id) on delete cascade, forecast_date date not null, projected_demand numeric not null default 0 check(projected_demand>=0), projected_stock numeric not null default 0, days_to_stockout numeric null, confidence numeric not null default 0 check(confidence between 0 and 100), model_version text not null default 'inventory-v1', created_at timestamptz not null default now(), unique(product_id,forecast_date,model_version)); alter table public.inventory_forecasts enable row level security; drop policy if exists inventory_forecasts_owner_select on public.inventory_forecasts; create policy inventory_forecasts_owner_select on public.inventory_forecasts for select to authenticated using(exists(select 1 from public.stores s where s.id=store_id and s.vendor_id=auth.uid())); create index if not exists inventory_forecasts_store_date_idx on public.inventory_forecasts(store_id,forecast_date desc);
create table if not exists public.supplier_performance_daily (supplier_id uuid not null references auth.users(id) on delete cascade, metric_date date not null, orders_count integer not null default 0, delivered_count integer not null default 0, cancelled_count integer not null default 0, disputed_count integer not null default 0, avg_rating numeric null, on_time_rate numeric null, score numeric null, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), primary key(supplier_id,metric_date)); alter table public.supplier_performance_daily enable row level security; drop policy if exists supplier_performance_owner_select on public.supplier_performance_daily; create policy supplier_performance_owner_select on public.supplier_performance_daily for select to authenticated using(supplier_id=auth.uid()); create index if not exists supplier_performance_date_idx on public.supplier_performance_daily(metric_date desc);
